DECLARE @pkMasterSkuData NVARCHAR(128); SELECT @pkMasterSkuData=name FROM sys.key_constraints WHERE parent_object_id=OBJECT_ID(N'MasterSkuData') AND type='PK'; IF @pkMasterSkuData IS NOT NULL BEGIN DECLARE @dropMasterSkuData NVARCHAR(MAX); SET @dropMasterSkuData=N'ALTER TABLE MasterSkuData DROP CONSTRAINT '+QUOTENAME(@pkMasterSkuData); EXEC(@dropMasterSkuData); END;
ALTER TABLE MasterSkuData ALTER COLUMN SkuId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL;
ALTER TABLE MasterSkuData ADD PRIMARY KEY(SkuId);
DECLARE @pkMasterShopData NVARCHAR(128); SELECT @pkMasterShopData=name FROM sys.key_constraints WHERE parent_object_id=OBJECT_ID(N'MasterShopData') AND type='PK'; IF @pkMasterShopData IS NOT NULL BEGIN DECLARE @dropMasterShopData NVARCHAR(MAX); SET @dropMasterShopData=N'ALTER TABLE MasterShopData DROP CONSTRAINT '+QUOTENAME(@pkMasterShopData); EXEC(@dropMasterShopData); END;
ALTER TABLE MasterShopData ALTER COLUMN ShopId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL;
ALTER TABLE MasterShopData ADD PRIMARY KEY(ShopId);
DECLARE @pkMasterMappingState NVARCHAR(128); SELECT @pkMasterMappingState=name FROM sys.key_constraints WHERE parent_object_id=OBJECT_ID(N'MasterMappingState') AND type='PK'; IF @pkMasterMappingState IS NOT NULL BEGIN DECLARE @dropMasterMappingState NVARCHAR(MAX); SET @dropMasterMappingState=N'ALTER TABLE MasterMappingState DROP CONSTRAINT '+QUOTENAME(@pkMasterMappingState); EXEC(@dropMasterMappingState); END;
ALTER TABLE MasterMappingState ALTER COLUMN TenantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL;
ALTER TABLE MasterMappingState ALTER COLUMN Platform NVARCHAR(30) COLLATE Latin1_General_100_BIN2 NOT NULL;
ALTER TABLE MasterMappingState ALTER COLUMN ShopId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL;
ALTER TABLE MasterMappingState ALTER COLUMN ProductId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL;
ALTER TABLE MasterMappingState ALTER COLUMN VariantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL;
ALTER TABLE MasterMappingState ADD PRIMARY KEY(TenantId,Platform,ShopId,ProductId,VariantId);
CREATE TABLE OpeningConfiguration(Id BIGINT PRIMARY KEY CHECK(Id=1),RequireDifferentApprover BIGINT NOT NULL CHECK(RequireDifferentApprover IN(0,1)),Version BIGINT NOT NULL);
CREATE TABLE OpeningPolicyChanges(Id NVARCHAR(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,ExpectedVersion BIGINT NOT NULL,RequireDifferentApprover BIGINT NOT NULL,RequestedBy NVARCHAR(200) COLLATE Latin1_General_100_BIN2 NOT NULL,State NVARCHAR(30) COLLATE Latin1_General_100_BIN2 NOT NULL,Version BIGINT NOT NULL,CreatedAt NVARCHAR(50) COLLATE Latin1_General_100_BIN2 NOT NULL);
ALTER TABLE OpeningDocuments ADD RequireDifferentApprover BIGINT NOT NULL DEFAULT 0;
ALTER TABLE OpeningDocuments ADD PolicyVersion BIGINT NOT NULL DEFAULT 0;
CREATE TABLE PlatformOrderLines(OrderId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES SalesOrders(Id),LineId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,ProductId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,VariantId NVARCHAR(100) COLLATE Latin1_General_100_BIN2 NOT NULL,PRIMARY KEY(OrderId,LineId));
CREATE INDEX IX_PlatformOrderLines_Key ON PlatformOrderLines(ProductId,VariantId,OrderId);
